import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'

/**
 * Cycle estimates (CAL-05/06, blueprint 05 §8).
 *
 * These are averages of what the owner logged — nothing more. The output always
 * carries a range and a confidence, because a single number here would read as
 * a medical prediction, which this app must never make. No contraception advice
 * is derived from any of it.
 */

/** Deliberately coarse: three buckets, and never higher than "sedang". */
export type CycleConfidence = 'belum cukup' | 'kasar' | 'sedang'

export interface CycleEstimate {
  /** Average gap between logged starts, or null when there is not enough data. */
  averageLength: number | null
  /** Spread between shortest and longest observed cycle. */
  variationDays: number | null
  nextStart: string | null
  /** Plausible window for the next start, widened by observed variation. */
  nextStartRange: [string, string] | null
  /** Rough fertile window estimate. Absent below four logged cycles. */
  fertileWindow: [string, string] | null
  confidence: CycleConfidence
  /** How many complete cycles the estimate is based on. */
  basedOnCycles: number
}

export function estimate(startDates: string[], today = new Date()): CycleEstimate {
  const starts = [...new Set(startDates)].sort()
  const gaps: number[] = []
  for (let i = 1; i < starts.length; i++) {
    const g = differenceInCalendarDays(parseISO(starts[i]!), parseISO(starts[i - 1]!))
    // Drop obviously mistyped entries rather than letting them skew the average.
    if (g >= 15 && g <= 60) gaps.push(g)
  }

  const empty: CycleEstimate = {
    averageLength: null,
    variationDays: null,
    nextStart: null,
    nextStartRange: null,
    fertileWindow: null,
    confidence: 'belum cukup',
    basedOnCycles: gaps.length,
  }
  if (gaps.length === 0 || starts.length === 0) return empty

  const avg = Math.round(gaps.reduce((s, g) => s + g, 0) / gaps.length)
  const variation = Math.max(...gaps) - Math.min(...gaps)
  const last = parseISO(starts[starts.length - 1]!)

  // Half the observed spread on each side, floored at ±2 days: even a perfectly
  // regular history does not justify claiming a single certain date.
  const pad = Math.max(2, Math.ceil(variation / 2))

  // Walk forward so the estimate stays useful after months away — but only past
  // dates that are already outside the uncertainty window. A period two days
  // late is late, not a reason to point at next month.
  let next = addDays(last, avg)
  while (differenceInCalendarDays(next, today) < -pad) next = addDays(next, avg)
  const confidence = gaps.length >= 4 ? 'sedang' : 'kasar'

  return {
    averageLength: avg,
    variationDays: variation,
    nextStart: format(next, 'yyyy-MM-dd'),
    nextStartRange: [format(addDays(next, -pad), 'yyyy-MM-dd'), format(addDays(next, pad), 'yyyy-MM-dd')],
    // Luteal phase is the steadier half; ovulation is roughly avg-14 from the
    // next start. Only offered once there is a real history behind it.
    fertileWindow:
      gaps.length >= 4
        ? [format(addDays(next, -19), 'yyyy-MM-dd'), format(addDays(next, -12), 'yyyy-MM-dd')]
        : null,
    confidence,
    basedOnCycles: gaps.length,
  }
}

/**
 * What a partner sees at each sharing level. The owner picks the level; the app
 * never widens it, and mood is never included as a derived claim.
 */
export type CycleShareLevel = 'none' | 'dates_only' | 'phase' | 'support' | 'full'

/** Levels in ascending disclosure order; labels come from `share.*` keys. */
export const SHARE_LEVELS: readonly CycleShareLevel[] = [
  'none',
  'dates_only',
  'phase',
  'support',
  'full',
]
